CREATE TABLE authz_int.locks (type text PRIMARY KEY, n bigint NOT NULL);

-- a row for each row a share, a key or a request named (authz_int.mark_row), until that row is gone
CREATE TABLE authz_int.row_marks (type text, id text, n bigint NOT NULL DEFAULT 0, PRIMARY KEY (type, id));

-- each inheritance table's definition and the tables it reads, to keep it on the next apply if they are the same
CREATE TABLE authz_int.trees (name text PRIMARY KEY, hash text NOT NULL, oids oid[] NOT NULL);

INSERT INTO authz_int.trees VALUES
  ('doc__parent_shortcut__tree2', '27a8270c680f58ce30b05c018a8e032c', ARRAY[to_regclass('"alt"."doc_links"')::oid, to_regclass('"alt"."docs"')::oid, to_regclass('authz.shares')::oid]::oid[]);

-- The subject key of a share (as the policy writes it: user, team#member, user:*, anyone, link)
CREATE FUNCTION authz_int.subject_key(p_type text, p_id text, p_relation text) RETURNS text
LANGUAGE sql IMMUTABLE AS $f$
  SELECT CASE WHEN p_type IN ('anyone', 'link') THEN p_type
              WHEN p_id = '*' AND p_relation = '' THEN p_type || ':*'
              WHEN p_relation <> '' THEN p_type || '#' || p_relation
              ELSE p_type END $f$;

CREATE TABLE authz_int.shared_relations (object_type text, relation text, subject text, shared_by text, required text[], loc text, PRIMARY KEY (object_type, relation, subject));

INSERT INTO authz_int.shared_relations VALUES
  ('grp', 'member', 'grp#member', 'share', ARRAY[]::text[], 'share grp.member grp#member'),
  ('doc', 'reader', 'user', 'share', ARRAY['view']::text[], 'share doc.reader user'),
  ('doc', 'reader', 'grp#member', 'share', ARRAY['view']::text[], 'share doc.reader grp#member'),
  ('doc', 'writer', 'user', 'share', ARRAY['edit']::text[], 'share doc.writer user'),
  ('doc', 'banned', 'user', 'share', ARRAY[]::text[], 'share doc.banned user'),
  ('doc', 'banned', 'grp#member', 'share', ARRAY[]::text[], 'share doc.banned grp#member'),
  ('doc', 'shortcut', 'doc', 'share', ARRAY['view']::text[], 'share doc.shortcut doc');

DO $w$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz.shares g WHERE g.relation NOT LIKE 'role:%' AND NOT EXISTS (
    SELECT 1 FROM authz_int.shared_relations s WHERE s.object_type = g.object_type AND s.relation = g.relation
      AND s.subject = authz_int.subject_key(g.subject_type, g.subject_id, g.subject_relation));
  IF n > 0 THEN
    RAISE WARNING '% shares are for relations this policy does not declare as shared; they are kept, but grant nothing', n;
  END IF;
END $w$;

CREATE TABLE authz_int.role_subjects (object_type text, subject text, PRIMARY KEY (object_type, subject));

INSERT INTO authz_int.role_subjects VALUES ('doc', 'user'), ('doc', 'grp#member');

CREATE TABLE authz_int.role_grantable (object_type text, permission text, PRIMARY KEY (object_type, permission));

INSERT INTO authz_int.role_grantable VALUES ('doc', 'view'), ('doc', 'publish');

CREATE TABLE authz_int.caveats (name text PRIMARY KEY);

-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND c.relname LIKE 'shares\_obj\_%'
             AND c.relname <> ALL (ARRAY['shares_obj_user_bigint', 'shares_obj_grp_bigint', 'shares_obj_proj_bigint', 'shares_obj_doc_bigint']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
CREATE INDEX IF NOT EXISTS "shares_obj_user_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'user';
CREATE INDEX IF NOT EXISTS "shares_obj_grp_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'grp';
CREATE INDEX IF NOT EXISTS "shares_obj_proj_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'proj';
CREATE INDEX IF NOT EXISTS "shares_obj_doc_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'doc';

-- Scopes: what a token may do (policy 'scope' lines; 'read' is built in unless redefined)
CREATE TABLE authz_int.scope_items (scope text, kind text, qual text, word text);
INSERT INTO authz_int.scope_items VALUES
  ('read', 'cmd', NULL, 'select'),
  ('read', 'perm', NULL, '*');

-- the scopes this transaction is limited to (NULL: not limited); believed only if signed, like the user. (session_ok()
-- raises for a session that isn't signed rather than say false: the first branch is only what one would get if it
-- ever did, no scope at all)
CREATE FUNCTION authz_int.scopes_active() RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT CASE WHEN NOT authz_int.session_ok() THEN ARRAY[]::text[]
              WHEN coalesce(current_setting('authz.scopes', true), '') = '' THEN NULL
              ELSE ARRAY(SELECT btrim(x) FROM unnest(string_to_array(current_setting('authz.scopes', true), ',')) x
                         WHERE btrim(x) <> '') END $f$;
-- may this transaction run a command on a table?
CREATE FUNCTION authz_int.scope_cmd(p_table text, p_cmd text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                              AND i.word = p_cmd AND (i.qual IS NULL OR i.qual = p_table))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction ask about (or use) a permission?
CREATE FUNCTION authz_int.scope_perm(p_type text, p_perm text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'perm'
                              AND (i.word = p_perm OR i.word = '*') AND (i.qual IS NULL OR i.qual = p_type))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction change anything? (not while viewing as someone, not with read-only scopes)
CREATE FUNCTION authz_int.writable() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(current_setting('authz.acting_user', true), '') = ''
     AND (s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                               AND i.word <> 'select'))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
CREATE FUNCTION authz_int.check_writable() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT authz_int.writable() THEN
    RAISE EXCEPTION 'this session is read-only (viewing as someone else, or a read-only token)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
END $f$;
-- custom roles, access requests, access reviews, break-glass, a key of one's own and view-as are for users: a
-- service signed in (another principal type) is refused, saying so, even one the policy gives the permission the
-- call asks for. Nobody signed in passes: each caller that needs a user says so itself (sign in to ..., AZ714)
CREATE FUNCTION authz_int.users_only(p_what text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text; v_id text;
BEGIN
  SELECT p.principal_type, p.principal_id INTO v_type, v_id FROM authz.principal() p;
  IF v_type <> 'user' THEN
    RAISE EXCEPTION '% is for users, not services (% % is signed in)', p_what, v_type, v_id
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ715';
  END IF;
END $f$;
-- the role that called (inside SECURITY DEFINER functions current_user is the owner)
CREATE FUNCTION authz_int.caller_role() RETURNS text
LANGUAGE sql STABLE AS $f$
  SELECT CASE WHEN current_setting('role') = 'none' THEN session_user::text ELSE current_setting('role') END $f$;
-- The caller is an administrator, not the app: a superuser, BYPASSRLS, or the policy's owner (or a member of it)
CREATE FUNCTION authz_int.caller_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce((SELECT r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid, n.nspowner, 'MEMBER')
                   FROM pg_roles r, pg_namespace n
                   WHERE r.rolname = authz_int.caller_role() AND n.nspname = 'authz_int'), false) $f$;
-- one row in the audit trail
CREATE FUNCTION authz_int.audit(p_action text, p_object_type text, p_object_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text, p_detail jsonb) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation,
                           subject_type, subject_id, subject_relation, detail, reason)
  VALUES (authz_int.caller_role(), authz_int.actor(),
          nullif(current_setting('authz.acting_user', true), ''), p_action, p_object_type, p_object_id, p_relation,
          p_subject_type, p_subject_id, p_subject_relation, p_detail,
          nullif(current_setting('authz_ctx.reason', true), '')) $f$;

-- The change feed: objects whose access may have changed. Consumers poll authz.changes_since(pos).
-- NOTIFY on channel authz_changes only with INSERT INTO authz.settings VALUES ('notify_changes', 'on'):
-- Postgres commits notifying transactions one at a time, so it would queue every write.
CREATE FUNCTION authz_int.changed(p_type text, p_ids text[], p_cause text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_pos bigint;
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  INSERT INTO authz.changes (object_type, object_ids, cause) VALUES (p_type, p_ids, p_cause) RETURNING pos INTO v_pos;
  IF (SELECT s.value FROM authz.settings s WHERE s.key = 'notify_changes') = 'on' THEN
    PERFORM pg_notify('authz_changes', v_pos::text);
  END IF;
END $f$;
-- Read the feed from a position: SELECT * FROM authz.changes_since(0)  (administrators, sync jobs).
-- A reader behind what authz.trim_changes() removed gets an error: it must read everything again.
CREATE OR REPLACE FUNCTION authz.changes_since(p_pos bigint, p_limit int DEFAULT 1000) RETURNS SETOF authz.changes
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_to bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to');
BEGIN
  IF p_pos < v_to THEN
    RAISE EXCEPTION 'the change feed up to position % was trimmed: read everything again, then follow from there', v_to
      USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ712';
  END IF;
  RETURN QUERY SELECT * FROM authz.changes WHERE pos > p_pos ORDER BY pos LIMIT p_limit;
END $f$;

-- Retention (both grow forever otherwise); schedule these, with pg_cron or the app's jobs.
-- The feed: entries older than p_keep, by default the setting changes_keep, else 7 days.
CREATE OR REPLACE FUNCTION authz.trim_changes(p_keep interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_keep interval := coalesce(p_keep, (SELECT s.value::interval FROM authz.settings s WHERE s.key = 'changes_keep'),
                              interval '7 days');
  v_to bigint; n bigint;
BEGIN
  SELECT max(c.pos) INTO v_to FROM authz.changes c WHERE c.at < now() - v_keep;
  IF v_to IS NULL THEN RETURN 0; END IF;
  DELETE FROM authz.changes c WHERE c.pos <= v_to;
  GET DIAGNOSTICS n = ROW_COUNT;
  INSERT INTO authz.settings VALUES ('changes_trimmed_to', v_to::text)
    ON CONFLICT (key) DO UPDATE SET value = greatest(authz.settings.value::bigint, v_to)::text;
  RETURN n;
END $f$;
-- The audit trail: entries older than p_keep (no default: how long to keep it is a compliance
-- decision). The trim itself is recorded in the audit trail.
CREATE OR REPLACE FUNCTION authz.trim_audit(p_keep interval) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_before timestamptz; n bigint;
BEGIN
  IF p_keep IS NULL OR p_keep < interval '0' THEN
    RAISE EXCEPTION 'say how long to keep the audit trail, e.g. authz.trim_audit(interval ''2 years'')' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  v_before := now() - p_keep;
  -- the one way past the trigger is DDL, as the owner, here: nothing a session can set lets a DELETE through
  -- (ALTER TABLE takes an exclusive lock on the trail until the transaction ends); it is on again as it was, in
  -- every replication role
  ALTER TABLE authz.audit DISABLE TRIGGER authz_audit_append_only;
  DELETE FROM authz.audit a WHERE a.at < v_before;
  GET DIAGNOSTICS n = ROW_COUNT;
  ALTER TABLE authz.audit ENABLE ALWAYS TRIGGER authz_audit_append_only;
  INSERT INTO authz.audit (db_role, user_id, action, detail)
  VALUES (authz_int.caller_role(), authz_int.actor(), 'trim_audit',
          jsonb_build_object('before', v_before, 'rows', n));
  RETURN n;
END $f$;

-- The audit trail only grows, except through authz.trim_audit(). Its triggers fire in every replication role
-- (ENABLE ALWAYS): session_replication_role = replica, which turns ordinary triggers off, leaves them on. A
-- subscription's worker applies its publisher's rows in that role, and the trims made there with them: a process
-- Postgres lists as one (pg_stat_subscription), which no session can make itself
CREATE FUNCTION authz_int.audit_is_append_only() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_stat_subscription s WHERE s.pid = pg_catalog.pg_backend_pid()) THEN
    IF TG_OP = 'UPDATE' THEN
      RETURN NEW;
    END IF;
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'the audit trail cannot be changed' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ711';
END $f$;
CREATE TRIGGER authz_audit_append_only BEFORE UPDATE OR DELETE ON authz.audit
  FOR EACH ROW EXECUTE FUNCTION authz_int.audit_is_append_only();
ALTER TABLE authz.audit ENABLE ALWAYS TRIGGER authz_audit_append_only;
CREATE TRIGGER authz_audit_no_truncate BEFORE TRUNCATE ON authz.audit
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int.audit_is_append_only();
ALTER TABLE authz.audit ENABLE ALWAYS TRIGGER authz_audit_no_truncate;

-- shares and role assignments
CREATE FUNCTION authz_int.on_share() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.shares;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  PERFORM authz_int.audit(CASE TG_OP WHEN 'INSERT' THEN 'share' WHEN 'DELETE' THEN 'unshare' ELSE 'share_changed' END,
    r.object_type, r.object_id, r.relation, r.subject_type,
    CASE WHEN r.subject_type = 'link' THEN '(link)' ELSE r.subject_id END, r.subject_relation,
    jsonb_strip_nulls(jsonb_build_object('expires_at', r.expires_at, 'starts_at', r.starts_at, 'caveat', r.caveat,
                                         'created_by', r.created_by)));
  PERFORM authz_int.changed(r.object_type, ARRAY[r.object_id], 'share');
  IF TG_OP = 'UPDATE' AND OLD.object_id <> NEW.object_id THEN
    PERFORM authz_int.changed(OLD.object_type, ARRAY[OLD.object_id], 'share');
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_share_audit AFTER INSERT OR UPDATE OR DELETE ON authz.shares
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_share();
CREATE FUNCTION authz_int.on_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_TABLE_NAME = 'roles' THEN
    PERFORM authz_int.audit(lower(TG_OP) || '_role', CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_type ELSE NEW.owner_type END,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_id ELSE NEW.owner_id END, NULL, NULL, NULL, NULL,
      to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END));
  ELSE
    PERFORM authz_int.audit(CASE TG_OP WHEN 'DELETE' THEN 'role_permission_removed' ELSE 'role_permission_added' END,
      NULL, NULL, 'role:' || CASE WHEN TG_OP = 'DELETE' THEN OLD.role_id ELSE NEW.role_id END, NULL, NULL, NULL,
      jsonb_build_object('permission', CASE WHEN TG_OP = 'DELETE' THEN OLD.permission ELSE NEW.permission END));
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_audit AFTER INSERT OR UPDATE OR DELETE ON authz.roles
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();
CREATE TRIGGER authz_role_perm_audit AFTER INSERT OR DELETE ON authz.role_permissions
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares stored with ids that aren't canonical for their type's key ('007' for a bigint, an uppercase uuid) are
-- made canonical, since the sweep below and the triggers compare text: stored as canonical when written, an id
-- isn't any more once the type of its key changes (text to bigint, say). One that then repeats a share already
-- stored goes, the first made staying
CREATE TEMP TABLE authz_uncanonical ON COMMIT DROP AS
  SELECT g.ctid AS row, authz_int.canon(g.object_type, g.object_id) AS object_id,
         authz_int.canon(g.subject_type, g.subject_id) AS subject_id
  FROM authz.shares g
  WHERE g.object_id IS DISTINCT FROM authz_int.canon(g.object_type, g.object_id)
     OR g.subject_id IS DISTINCT FROM authz_int.canon(g.subject_type, g.subject_id);
DELETE FROM authz.shares g USING authz_uncanonical u
WHERE g.ctid = u.row AND EXISTS (
  SELECT 1 FROM authz.shares c WHERE c.object_type = g.object_type AND c.object_id = u.object_id AND c.relation = g.relation
    AND c.subject_type = g.subject_type AND c.subject_id = u.subject_id AND c.subject_relation = g.subject_relation);
DELETE FROM authz.shares g USING (
  SELECT u.row, row_number() OVER (PARTITION BY s.object_type, u.object_id, s.relation, s.subject_type, u.subject_id,
                                   s.subject_relation ORDER BY s.created_at, u.row) AS n
  FROM authz_uncanonical u JOIN authz.shares s ON s.ctid = u.row) d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares g SET object_id = u.object_id, subject_id = u.subject_id FROM authz_uncanonical u WHERE g.ctid = u.row;
DROP TABLE authz_uncanonical;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "alt"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "alt"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'grp' AND NOT EXISTS (SELECT 1 FROM "alt"."groups" x WHERE x."gid"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'grp' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "alt"."groups" x WHERE x."gid"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'proj' AND NOT EXISTS (SELECT 1 FROM "alt"."projects" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'proj' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "alt"."projects" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'doc' AND NOT EXISTS (SELECT 1 FROM "alt"."docs" x WHERE x."doc_no"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'doc' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "alt"."docs" x WHERE x."doc_no"::text = g.subject_id);
-- ...and so are the API keys of principals that no longer exist
DELETE FROM authz.api_keys k WHERE k.principal_type = 'user' AND NOT EXISTS (SELECT 1 FROM "alt"."users" x WHERE x."id"::text = k.user_id);
-- ...and pending access requests whose requester no longer exists are cancelled (not those whose object
-- doesn't: a request for a missing object is allowed, so that asking doesn't tell which hidden ones exist)
UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its requester is gone' WHERE r.status = 'pending' AND NOT EXISTS (SELECT 1 FROM "alt"."users" x WHERE x."id"::text = r.requester);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- 'shared if {...}' conditions (they run as the policy's owner, like permissions)
CREATE FUNCTION authz_int.share_if(p_key text, p_object_id text, p_subject_type text, p_subject_id text,
  p_subject_relation text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_key
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;

-- `roles : ... from rel`: a role counts on an object only if what rel links the object to owns it
CREATE FUNCTION authz_int.role_owned(p_type text, p_id text, p_owner_type text, p_owner_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_type
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;
-- the type that owns the custom roles of an object type, when the policy says (from rel)
CREATE FUNCTION authz_int.role_owner_type(p_object_type text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_object_type
    WHEN NULL THEN NULL;
    ELSE RETURN NULL;
  END CASE;
END $f$;
-- relations ('role:<id>') of the custom roles that include a permission
CREATE FUNCTION authz_int.role_relations(p_type text, p_perm text) RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(array_agg('role:' || r.id), '{}') FROM authz.roles r
  JOIN authz.role_permissions p ON p.role_id = r.id
  WHERE r.object_type = p_type AND p.permission = p_perm $f$;
-- deleting a role removes its assignments
CREATE FUNCTION authz_int.role_gone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  DELETE FROM authz.shares WHERE relation IN (SELECT 'role:' || o.id FROM old_rows o);
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_gone AFTER DELETE ON authz.roles
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int.role_gone();

-- a share, a key or a request naming a row marks it (a new version of its mark, which a transaction that can't
-- see it and then deletes the row, or changes its id, writes too: forget_marks)
CREATE FUNCTION authz_int.mark_row(p_type text, p_id text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz_int.row_marks AS m (type, id) VALUES (p_type, p_id)
  ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1 $f$;
-- rows that are gone, or whose id changed: their marks go too. In a transaction whose snapshot may be older than a
-- share, key or request naming one of them (not READ COMMITTED), the marks are written first: if one was made since,
-- that fails to serialize (40001), rather than leave what the deletes after can't see
CREATE FUNCTION authz_int.forget_marks(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    INSERT INTO authz_int.row_marks AS m (type, id) SELECT DISTINCT p_type, x FROM unnest(p_ids) x
    ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1;
  END IF;
  DELETE FROM authz_int.row_marks WHERE type = p_type AND id = ANY (p_ids);
END $f$;
-- whether a row is there, locked (FOR KEY SHARE) until the transaction ends, as authz.share locks what it shares
CREATE FUNCTION authz_int.hold(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean;
BEGIN
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  -- (the key's type by a subquery, never a variable: pg_input_is_valid takes a variable's first value for every
  -- later call from the same line, so a uuid key checked after a bigint one would be invalid)
  IF v_tbl IS NULL OR NOT pg_catalog.pg_input_is_valid(p_id, (SELECT t.keytype FROM authz_int.types t WHERE t.name = p_type)) THEN
    RETURN false;
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  RETURN v_found;
END $f$;

-- doc: each row with every ancestor it inherits from, through parent while {coalesce((not locked), false) AND coalesce((NOT coalesce((exists (select 1 from alt.holds h where h.target = this.up)), false)), false)}
CREATE TABLE authz_int."doc__parent__tree" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  CONSTRAINT "doc__parent__tree_pkey" PRIMARY KEY (descendant, ancestor));
CREATE INDEX "doc__parent__tree_ancestor_idx" ON authz_int."doc__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('doc', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."doc__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."doc__parent__tree";
    ALTER TABLE authz_keep."doc__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('doc__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."doc__parent__tree_links" AS
  (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL)
  UNION ALL
  (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL);

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."doc__parent__tree_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."doc_no", x."doc_no" FROM "alt"."docs" x WHERE x."doc_no" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "alt"."docs" c WHERE c."doc_no" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((coalesce((not locked), false) AND coalesce((NOT coalesce((exists (select 1 from alt.holds h where h.target = c.up)), false)), false)), false)))
      AND EXISTS (SELECT 1 FROM "alt"."docs" p WHERE p."doc_no" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- the conditions on each row (and the type's where)
CREATE VIEW authz_int."doc__parent__tree_conds" AS
  SELECT r."doc_no" AS id, ARRAY[coalesce((coalesce((not locked), false) AND coalesce((NOT coalesce((exists (select 1 from alt.holds h where h.target = r.up)), false)), false)), false)] AS v FROM "alt"."docs" r;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."doc__parent__tree_links"'::regclass, 'authz_int."doc__parent__tree_conds"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 33', d.fn;
  END LOOP;
END $imm$;

-- ...as last applied (they read other rows or tables, so changes there are re-checked)
CREATE TABLE authz_int."doc__parent__tree_cond_cache" (id bigint PRIMARY KEY, v boolean[] NOT NULL);
-- the tree's own table, if a condition reads it through a query (found when applied)
CREATE TABLE authz_int."doc__parent__tree_reads" (rel regclass PRIMARY KEY);

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."doc__parent__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  DELETE FROM authz_int."doc__parent__tree" WHERE descendant = ANY (affected);
  INSERT INTO authz_int."doc__parent__tree" (descendant, ancestor)
  SELECT o_descendant, o_ancestor FROM authz_int."doc__parent__tree_compute"(affected);
  DELETE FROM authz_int."doc__parent__tree_cond_cache" WHERE id = ANY (affected);
  INSERT INTO authz_int."doc__parent__tree_cond_cache" SELECT id, v FROM authz_int."doc__parent__tree_conds" WHERE id = ANY (affected);
  PERFORM authz_int.changed('doc', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."doc__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  DELETE FROM authz_int."doc__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "doc_no" AS k, row_number() OVER () AS n FROM "alt"."docs") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."doc__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."doc__parent__tree_compute"(batch);
  END LOOP;
  DELETE FROM authz_int."doc__parent__tree_cond_cache";
  INSERT INTO authz_int."doc__parent__tree_cond_cache" SELECT id, v FROM authz_int."doc__parent__tree_conds";
END $f$;
CREATE FUNCTION authz_int."doc__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."doc__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."doc__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "doc_no" AS k, row_number() OVER () AS n FROM "alt"."docs") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."doc__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."doc__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."doc__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "alt"."docs" x WHERE x."doc_no" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true
     AND NOT EXISTS ((SELECT id, v FROM authz_int."doc__parent__tree_conds" EXCEPT SELECT id, v FROM authz_int."doc__parent__tree_cond_cache")
                     UNION ALL
                     (SELECT id, v FROM authz_int."doc__parent__tree_cond_cache" EXCEPT SELECT id, v FROM authz_int."doc__parent__tree_conds"));
END $f$;

-- re-evaluate the conditions after a change to what they read
CREATE FUNCTION authz_int."doc__parent__tree_recheck"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  PERFORM authz_int."doc__parent__tree_refresh"(ARRAY(
    SELECT coalesce(c.id, k.id) FROM authz_int."doc__parent__tree_conds" c FULL JOIN authz_int."doc__parent__tree_cond_cache" k ON k.id = c.id
    WHERE c.v IS DISTINCT FROM k.v));
END $f$;
CREATE FUNCTION authz_int."doc__parent__tree_on_deps"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."doc__parent__tree_recheck"(); RETURN NULL; END $f$;

-- find the tables the conditions read and watch them; for the tree's own tables, only note those read
-- @locks SHARE ROW EXCLUSIVE: the tables the inheritance conditions read (line 33)
DO $dep$
DECLARE d record;
BEGIN
  -- the conditions over an empty copy of each table, so that the row itself isn't among what they read
  CREATE TEMP TABLE authz_reads1 (LIKE "alt"."docs");
  CREATE TEMP VIEW authz_reads AS
    SELECT coalesce((coalesce((not locked), false) AND coalesce((NOT coalesce((exists (select 1 from alt.holds h where h.target = r.up)), false)), false)), false) AS v FROM pg_temp.authz_reads1 r;
  FOR d IN SELECT DISTINCT c.oid::regclass AS rel, c.relkind
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_class c ON c.oid = dep.refobjid AND dep.refclassid = 'pg_class'::regclass
           WHERE w.ev_class = 'pg_temp.authz_reads'::regclass
             AND c.oid NOT IN (w.ev_class, 'pg_temp.authz_reads1'::regclass) LOOP
    IF d.relkind NOT IN ('r', 'p') THEN
      RAISE EXCEPTION '%: a condition used for inheritance reads %, which is not a table; read its tables directly [AZ604]',
        'line 33', d.rel;
    ELSIF d.rel IN ('"alt"."docs"'::regclass) THEN
      INSERT INTO authz_int."doc__parent__tree_reads" VALUES (d.rel);
    ELSE
      EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON %s '
                     'FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_deps"()', 'authz_doc__parent__tree_dep', d.rel);
    END IF;
  END LOOP;
  DROP VIEW pg_temp.authz_reads;
  DROP TABLE pg_temp.authz_reads1;
END $dep$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."doc__parent__tree_parents" AS
  SELECT r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL;
CREATE FUNCTION authz_int."doc__parent__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."doc__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'doc % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."doc__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids bigint[]; shift boolean := false; wrote boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."doc_no" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    wrote := EXISTS (SELECT 1 FROM new_rows);
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."doc_no" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."doc_no" = o."doc_no")
      UNION SELECT n."doc_no" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."doc_no" = n."doc_no"));
    shift := false;
    ids := ARRAY(
      SELECT n."doc_no" FROM new_rows n JOIN old_rows o ON o."doc_no" = n."doc_no"
      WHERE n."up" IS DISTINCT FROM o."up"
         OR (SELECT coalesce((coalesce((not locked), false) AND coalesce((NOT coalesce((exists (select 1 from alt.holds h where h.target = r.up)), false)), false)), false) FROM (SELECT n.*) r) IS DISTINCT FROM (SELECT coalesce((coalesce((not locked), false) AND coalesce((NOT coalesce((exists (select 1 from alt.holds h where h.target = r.up)), false)), false)), false) FROM (SELECT o.*) r)
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."doc_no" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."doc__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."doc__parent__tree_refresh"(ids, shift);
  END IF;
  -- a condition that reads this table through a query may hold differently on other rows now
  IF coalesce(wrote, cardinality(ids) > 0) AND EXISTS (SELECT 1 FROM authz_int."doc__parent__tree_reads" WHERE rel = TG_RELID::regclass) THEN
    PERFORM authz_int."doc__parent__tree_recheck"();
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_doc__parent__tree_ins" AFTER INSERT ON "alt"."docs"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_rows"();
CREATE TRIGGER "authz_doc__parent__tree_upd" AFTER UPDATE ON "alt"."docs"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_rows"();
CREATE TRIGGER "authz_doc__parent__tree_del" AFTER DELETE ON "alt"."docs"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_rows"();
CREATE TRIGGER "authz_doc__parent__tree_trunc" AFTER TRUNCATE ON "alt"."docs"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_truncate"();

-- links stored in alt.doc_links
CREATE FUNCTION authz_int."doc__parent__tree_on_links1"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- one refresh for old and new links together: each refresh expects the rest to be current
  IF TG_OP = 'INSERT' THEN PERFORM authz_int."doc__parent__tree_refresh"(ARRAY(SELECT n."child" FROM new_rows n), false);
  ELSIF TG_OP = 'DELETE' THEN PERFORM authz_int."doc__parent__tree_refresh"(ARRAY(SELECT o."child" FROM old_rows o), false);
  ELSE PERFORM authz_int."doc__parent__tree_refresh"(ARRAY(SELECT n."child" FROM new_rows n UNION SELECT o."child" FROM old_rows o), false);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_doc__parent__tree_on_links1_ins" AFTER INSERT ON "alt"."doc_links"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_links1"();
CREATE TRIGGER "authz_doc__parent__tree_on_links1_upd" AFTER UPDATE ON "alt"."doc_links"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_links1"();
CREATE TRIGGER "authz_doc__parent__tree_on_links1_del" AFTER DELETE ON "alt"."doc_links"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_links1"();
CREATE TRIGGER "authz_doc__parent__tree_on_links1_trunc" AFTER TRUNCATE ON "alt"."doc_links"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent__tree_on_truncate"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'doc__parent__tree') THEN
    PERFORM authz_int."doc__parent__tree_rebuild"();
  END IF;
END $b$;

-- doc: each row with every ancestor it inherits from, through parent while {not exists (select 1 from alt.holds h where h.target = this.doc_no)}, shortcut
CREATE TABLE authz_int."doc__parent_shortcut__tree" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  CONSTRAINT "doc__parent_shortcut__tree_pkey" PRIMARY KEY (descendant, ancestor));
CREATE INDEX "doc__parent_shortcut__tree_ancestor_idx" ON authz_int."doc__parent_shortcut__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('doc', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."doc__parent_shortcut__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."doc__parent_shortcut__tree";
    ALTER TABLE authz_keep."doc__parent_shortcut__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('doc__parent_shortcut__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."doc__parent_shortcut__tree_links" AS
  (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL)
  UNION ALL
  (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL)
  UNION ALL
  (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '');

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."doc_no", x."doc_no" FROM "alt"."docs" x WHERE x."doc_no" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "alt"."docs" c WHERE c."doc_no" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '') x WHERE x._child = up._a OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((not exists (select 1 from alt.holds h where h.target = c.doc_no)), false)) OR e._link = 1)
      AND EXISTS (SELECT 1 FROM "alt"."docs" p WHERE p."doc_no" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- the conditions on each row (and the type's where)
CREATE VIEW authz_int."doc__parent_shortcut__tree_conds" AS
  SELECT r."doc_no" AS id, ARRAY[coalesce((not exists (select 1 from alt.holds h where h.target = r.doc_no)), false)] AS v FROM "alt"."docs" r;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."doc__parent_shortcut__tree_links"'::regclass, 'authz_int."doc__parent_shortcut__tree_conds"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 36', d.fn;
  END LOOP;
END $imm$;

-- ...as last applied (they read other rows or tables, so changes there are re-checked)
CREATE TABLE authz_int."doc__parent_shortcut__tree_cond_cache" (id bigint PRIMARY KEY, v boolean[] NOT NULL);
-- the tree's own table, if a condition reads it through a query (found when applied)
CREATE TABLE authz_int."doc__parent_shortcut__tree_reads" (rel regclass PRIMARY KEY);

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '') x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  DELETE FROM authz_int."doc__parent_shortcut__tree" WHERE descendant = ANY (affected);
  INSERT INTO authz_int."doc__parent_shortcut__tree" (descendant, ancestor)
  SELECT o_descendant, o_ancestor FROM authz_int."doc__parent_shortcut__tree_compute"(affected);
  DELETE FROM authz_int."doc__parent_shortcut__tree_cond_cache" WHERE id = ANY (affected);
  INSERT INTO authz_int."doc__parent_shortcut__tree_cond_cache" SELECT id, v FROM authz_int."doc__parent_shortcut__tree_conds" WHERE id = ANY (affected);
  PERFORM authz_int.changed('doc', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  DELETE FROM authz_int."doc__parent_shortcut__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "doc_no" AS k, row_number() OVER () AS n FROM "alt"."docs") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."doc__parent_shortcut__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."doc__parent_shortcut__tree_compute"(batch);
  END LOOP;
  DELETE FROM authz_int."doc__parent_shortcut__tree_cond_cache";
  INSERT INTO authz_int."doc__parent_shortcut__tree_cond_cache" SELECT id, v FROM authz_int."doc__parent_shortcut__tree_conds";
END $f$;
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."doc__parent_shortcut__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "doc_no" AS k, row_number() OVER () AS n FROM "alt"."docs") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."doc__parent_shortcut__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."doc__parent_shortcut__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."doc__parent_shortcut__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "alt"."docs" x WHERE x."doc_no" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true
     AND NOT EXISTS ((SELECT id, v FROM authz_int."doc__parent_shortcut__tree_conds" EXCEPT SELECT id, v FROM authz_int."doc__parent_shortcut__tree_cond_cache")
                     UNION ALL
                     (SELECT id, v FROM authz_int."doc__parent_shortcut__tree_cond_cache" EXCEPT SELECT id, v FROM authz_int."doc__parent_shortcut__tree_conds"));
END $f$;

-- re-evaluate the conditions after a change to what they read
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_recheck"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ARRAY(
    SELECT coalesce(c.id, k.id) FROM authz_int."doc__parent_shortcut__tree_conds" c FULL JOIN authz_int."doc__parent_shortcut__tree_cond_cache" k ON k.id = c.id
    WHERE c.v IS DISTINCT FROM k.v));
END $f$;
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_on_deps"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."doc__parent_shortcut__tree_recheck"(); RETURN NULL; END $f$;

-- find the tables the conditions read and watch them; for the tree's own tables, only note those read
-- @locks SHARE ROW EXCLUSIVE: the tables the inheritance conditions read (line 36)
DO $dep$
DECLARE d record;
BEGIN
  -- the conditions over an empty copy of each table, so that the row itself isn't among what they read
  CREATE TEMP TABLE authz_reads1 (LIKE "alt"."docs");
  CREATE TEMP VIEW authz_reads AS
    SELECT coalesce((not exists (select 1 from alt.holds h where h.target = r.doc_no)), false) AS v FROM pg_temp.authz_reads1 r;
  FOR d IN SELECT DISTINCT c.oid::regclass AS rel, c.relkind
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_class c ON c.oid = dep.refobjid AND dep.refclassid = 'pg_class'::regclass
           WHERE w.ev_class = 'pg_temp.authz_reads'::regclass
             AND c.oid NOT IN (w.ev_class, 'pg_temp.authz_reads1'::regclass) LOOP
    IF d.relkind NOT IN ('r', 'p') THEN
      RAISE EXCEPTION '%: a condition used for inheritance reads %, which is not a table; read its tables directly [AZ604]',
        'line 36', d.rel;
    ELSIF d.rel IN ('"alt"."docs"'::regclass) THEN
      INSERT INTO authz_int."doc__parent_shortcut__tree_reads" VALUES (d.rel);
    ELSE
      EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON %s '
                     'FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_deps"()', 'authz_doc__parent_shortcut__tree_dep', d.rel);
    END IF;
  END LOOP;
  DROP VIEW pg_temp.authz_reads;
  DROP TABLE pg_temp.authz_reads1;
END $dep$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."doc__parent_shortcut__tree_parents" AS
  SELECT r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL;
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."doc__parent_shortcut__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'doc % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids bigint[]; shift boolean := false; wrote boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."doc_no" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    wrote := EXISTS (SELECT 1 FROM new_rows);
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."doc_no" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."doc_no" = o."doc_no")
      UNION SELECT n."doc_no" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."doc_no" = n."doc_no"));
    shift := false;
    ids := ARRAY(
      SELECT n."doc_no" FROM new_rows n JOIN old_rows o ON o."doc_no" = n."doc_no"
      WHERE n."up" IS DISTINCT FROM o."up"
         OR (SELECT coalesce((not exists (select 1 from alt.holds h where h.target = r.doc_no)), false) FROM (SELECT n.*) r) IS DISTINCT FROM (SELECT coalesce((not exists (select 1 from alt.holds h where h.target = r.doc_no)), false) FROM (SELECT o.*) r)
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."doc_no" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."doc__parent_shortcut__tree_check_loops"(ids); END IF;
    PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ids, shift);
  END IF;
  -- a condition that reads this table through a query may hold differently on other rows now
  IF coalesce(wrote, cardinality(ids) > 0) AND EXISTS (SELECT 1 FROM authz_int."doc__parent_shortcut__tree_reads" WHERE rel = TG_RELID::regclass) THEN
    PERFORM authz_int."doc__parent_shortcut__tree_recheck"();
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_doc__parent_shortcut__tree_ins" AFTER INSERT ON "alt"."docs"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_rows"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_upd" AFTER UPDATE ON "alt"."docs"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_rows"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_del" AFTER DELETE ON "alt"."docs"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_rows"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_trunc" AFTER TRUNCATE ON "alt"."docs"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_truncate"();

-- links stored in alt.doc_links
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_on_links1"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- one refresh for old and new links together: each refresh expects the rest to be current
  IF TG_OP = 'INSERT' THEN PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ARRAY(SELECT n."child" FROM new_rows n), false);
  ELSIF TG_OP = 'DELETE' THEN PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ARRAY(SELECT o."child" FROM old_rows o), false);
  ELSE PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ARRAY(SELECT n."child" FROM new_rows n UNION SELECT o."child" FROM old_rows o), false);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_doc__parent_shortcut__tree_on_links1_ins" AFTER INSERT ON "alt"."doc_links"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_links1"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_on_links1_upd" AFTER UPDATE ON "alt"."doc_links"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_links1"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_on_links1_del" AFTER DELETE ON "alt"."doc_links"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_links1"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_on_links1_trunc" AFTER TRUNCATE ON "alt"."doc_links"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_truncate"();

-- links people make with authz.share(); they can't expire, since the closure is stored
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_on_shares"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE a_t text[]; a_i text[];
BEGIN
  -- one refresh for old and new links together: each refresh expects the rest to be current
  IF TG_OP = 'INSERT' THEN
    PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ARRAY(SELECT y.object_id::bigint FROM (SELECT x.object_type, x.object_id FROM new_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '')) y), false);
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ARRAY(SELECT y.object_id::bigint FROM (SELECT x.object_type, x.object_id FROM old_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '')) y), false);
  ELSE
    PERFORM authz_int."doc__parent_shortcut__tree_refresh"(ARRAY(SELECT y.object_id::bigint FROM (SELECT x.object_type, x.object_id FROM new_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '') UNION SELECT x.object_type, x.object_id FROM old_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '')) y), false);
  END IF;
  RETURN NULL;
END $f$;
DO $ex$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz.shares x
  WHERE (x.expires_at IS NOT NULL OR x.starts_at IS NOT NULL OR x.caveat IS NOT NULL) AND ((x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = ''));
  IF n > 0 THEN
    RAISE EXCEPTION '% existing shares of doc.shortcut have an expiry, a start time or a caveat, but links used for inheritance cannot; remove those (or the shares) first [AZ605]', n;
  END IF;
END $ex$;
CREATE FUNCTION authz_int."doc__parent_shortcut__tree_no_expiry"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RAISE EXCEPTION '%.% links are used for inheritance, so they cannot expire, start later or have a caveat',
    NEW.object_type, NEW.relation USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ605';
END $f$;
CREATE TRIGGER "authz_doc__parent_shortcut__tree_shares_ins" AFTER INSERT ON authz.shares
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_shares"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_shares_upd" AFTER UPDATE ON authz.shares
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_shares"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_shares_del" AFTER DELETE ON authz.shares
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_shares"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_shares_trunc" AFTER TRUNCATE ON authz.shares
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_on_truncate"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree_shares_expiry" BEFORE INSERT OR UPDATE ON authz.shares FOR EACH ROW
  WHEN ((NEW.expires_at IS NOT NULL OR NEW.starts_at IS NOT NULL OR NEW.caveat IS NOT NULL) AND ((NEW.object_type = 'doc' AND NEW.relation = 'shortcut' AND NEW.subject_type = 'doc' AND NEW.subject_relation = '')))
  EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree_no_expiry"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'doc__parent_shortcut__tree') THEN
    PERFORM authz_int."doc__parent_shortcut__tree_rebuild"();
  END IF;
END $b$;

-- doc: each row with every ancestor it inherits from, through parent, shortcut
CREATE TABLE authz_int."doc__parent_shortcut__tree2" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  CONSTRAINT "doc__parent_shortcut__tree2_pkey" PRIMARY KEY (descendant, ancestor));
CREATE INDEX "doc__parent_shortcut__tree2_ancestor_idx" ON authz_int."doc__parent_shortcut__tree2" (ancestor);
INSERT INTO authz_int.locks VALUES ('doc', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."doc__parent_shortcut__tree2"') IS NOT NULL THEN
    DROP TABLE authz_int."doc__parent_shortcut__tree2";
    ALTER TABLE authz_keep."doc__parent_shortcut__tree2" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('doc__parent_shortcut__tree2') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."doc__parent_shortcut__tree2_links" AS
  (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL)
  UNION ALL
  (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL)
  UNION ALL
  (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '');

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."doc_no", x."doc_no" FROM "alt"."docs" x WHERE x."doc_no" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "alt"."docs" c WHERE c."doc_no" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '') x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0 OR e._link = 1)
      AND EXISTS (SELECT 1 FROM "alt"."docs" p WHERE p."doc_no" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."doc__parent_shortcut__tree2_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 19', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_shift"(p_ids bigint[], p_below bigint[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched bigint[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."doc__parent_shortcut__tree2" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "alt"."docs" c ON c."doc_no" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '') x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0 OR e._link = 1) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."doc__parent_shortcut__tree2" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "alt"."docs" c ON c."doc_no" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '') x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."doc__parent_shortcut__tree2" u ON u.descendant = e._parent
    WHERE (e._link = 0 OR e._link = 1));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "alt"."docs" c ON c."doc_no" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '') x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0 OR e._link = 1)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."doc__parent_shortcut__tree2" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."doc__parent_shortcut__tree2" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."doc__parent_shortcut__tree2" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."doc__parent_shortcut__tree2" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, s."child" AS _child, s."parent" AS _parent FROM "alt"."doc_links" s WHERE s."parent" IS NOT NULL AND s."child" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 1 AS _link, g.object_id::bigint AS _child, g.subject_id::bigint AS _parent FROM authz.shares g WHERE g.object_type = 'doc' AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '') x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."doc__parent_shortcut__tree2_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."doc__parent_shortcut__tree2" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."doc__parent_shortcut__tree2" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."doc__parent_shortcut__tree2_compute"(affected);
  END IF;
  PERFORM authz_int.changed('doc', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  DELETE FROM authz_int."doc__parent_shortcut__tree2";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "doc_no" AS k, row_number() OVER () AS n FROM "alt"."docs") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."doc__parent_shortcut__tree2" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."doc__parent_shortcut__tree2_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."doc__parent_shortcut__tree2_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "doc_no" AS k, row_number() OVER () AS n FROM "alt"."docs") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."doc__parent_shortcut__tree2_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."doc__parent_shortcut__tree2"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."doc__parent_shortcut__tree2" s
             WHERE NOT EXISTS (SELECT 1 FROM "alt"."docs" x WHERE x."doc_no" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."doc__parent_shortcut__tree2_parents" AS
  SELECT r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL;
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."doc__parent_shortcut__tree2_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."doc_no" AS _child, r."up" AS _parent FROM "alt"."docs" r WHERE r."up" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'doc % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids bigint[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."doc_no" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."doc_no" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."doc_no" = o."doc_no")
      UNION SELECT n."doc_no" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."doc_no" = n."doc_no"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."doc_no" FROM new_rows n JOIN old_rows o ON o."doc_no" = n."doc_no"
      WHERE n."up" IS DISTINCT FROM o."up"
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."doc_no" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('doc');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."doc__parent_shortcut__tree2_check_loops"(ids); END IF;
    PERFORM authz_int."doc__parent_shortcut__tree2_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_ins" AFTER INSERT ON "alt"."docs"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_rows"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_upd" AFTER UPDATE ON "alt"."docs"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_rows"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_del" AFTER DELETE ON "alt"."docs"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_rows"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_trunc" AFTER TRUNCATE ON "alt"."docs"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_truncate"();

-- links stored in alt.doc_links
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_on_links1"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- one refresh for old and new links together: each refresh expects the rest to be current
  IF TG_OP = 'INSERT' THEN PERFORM authz_int."doc__parent_shortcut__tree2_refresh"(ARRAY(SELECT n."child" FROM new_rows n), true);
  ELSIF TG_OP = 'DELETE' THEN PERFORM authz_int."doc__parent_shortcut__tree2_refresh"(ARRAY(SELECT o."child" FROM old_rows o), true);
  ELSE PERFORM authz_int."doc__parent_shortcut__tree2_refresh"(ARRAY(SELECT n."child" FROM new_rows n UNION SELECT o."child" FROM old_rows o), true);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_on_links1_ins" AFTER INSERT ON "alt"."doc_links"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_links1"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_on_links1_upd" AFTER UPDATE ON "alt"."doc_links"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_links1"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_on_links1_del" AFTER DELETE ON "alt"."doc_links"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_links1"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_on_links1_trunc" AFTER TRUNCATE ON "alt"."doc_links"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_truncate"();

-- links people make with authz.share(); they can't expire, since the closure is stored
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_on_shares"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE a_t text[]; a_i text[];
BEGIN
  -- one refresh for old and new links together: each refresh expects the rest to be current
  IF TG_OP = 'INSERT' THEN
    PERFORM authz_int."doc__parent_shortcut__tree2_refresh"(ARRAY(SELECT y.object_id::bigint FROM (SELECT x.object_type, x.object_id FROM new_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '')) y), true);
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM authz_int."doc__parent_shortcut__tree2_refresh"(ARRAY(SELECT y.object_id::bigint FROM (SELECT x.object_type, x.object_id FROM old_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '')) y), true);
  ELSE
    PERFORM authz_int."doc__parent_shortcut__tree2_refresh"(ARRAY(SELECT y.object_id::bigint FROM (SELECT x.object_type, x.object_id FROM new_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '') UNION SELECT x.object_type, x.object_id FROM old_rows x WHERE (x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = '')) y), true);
  END IF;
  RETURN NULL;
END $f$;
DO $ex$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz.shares x
  WHERE (x.expires_at IS NOT NULL OR x.starts_at IS NOT NULL OR x.caveat IS NOT NULL) AND ((x.object_type = 'doc' AND x.relation = 'shortcut' AND x.subject_type = 'doc' AND x.subject_relation = ''));
  IF n > 0 THEN
    RAISE EXCEPTION '% existing shares of doc.shortcut have an expiry, a start time or a caveat, but links used for inheritance cannot; remove those (or the shares) first [AZ605]', n;
  END IF;
END $ex$;
CREATE FUNCTION authz_int."doc__parent_shortcut__tree2_no_expiry"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RAISE EXCEPTION '%.% links are used for inheritance, so they cannot expire, start later or have a caveat',
    NEW.object_type, NEW.relation USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ605';
END $f$;
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_shares_ins" AFTER INSERT ON authz.shares
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_shares"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_shares_upd" AFTER UPDATE ON authz.shares
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_shares"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_shares_del" AFTER DELETE ON authz.shares
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_shares"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_shares_trunc" AFTER TRUNCATE ON authz.shares
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_on_truncate"();
CREATE TRIGGER "authz_doc__parent_shortcut__tree2_shares_expiry" BEFORE INSERT OR UPDATE ON authz.shares FOR EACH ROW
  WHEN ((NEW.expires_at IS NOT NULL OR NEW.starts_at IS NOT NULL OR NEW.caveat IS NOT NULL) AND ((NEW.object_type = 'doc' AND NEW.relation = 'shortcut' AND NEW.subject_type = 'doc' AND NEW.subject_relation = '')))
  EXECUTE FUNCTION authz_int."doc__parent_shortcut__tree2_no_expiry"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'doc__parent_shortcut__tree2') THEN
    PERFORM authz_int."doc__parent_shortcut__tree2_rebuild"();
  END IF;
END $b$;

-- trees kept but no longer used (none, normally) go with the holding schema
DROP SCHEMA authz_keep CASCADE;

-- shares on user rows that are gone, or whose id changed, are removed (and their marks: forget_marks), and
-- the pending requests naming them are cancelled (requests_gone)
CREATE FUNCTION authz_int."user__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    DELETE FROM authz.shares WHERE object_type = 'user';
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id <> '*';      -- '*' (every one signed in) names no row
    DELETE FROM authz_int.row_marks WHERE type = 'user';
    PERFORM authz_int.requests_gone('user', NULL);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    PERFORM authz_int.requests_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT o."id"::text FROM old_rows o));
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id IN (SELECT o."id"::text FROM old_rows o);
