-- relationships kept in alt.doc_links
CREATE FUNCTION authz_int."rel_audit_1_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'doc' AS ot, x."child"::text AS oid, 'parent' AS rel, 'doc' AS st, x."parent"::text AS sid, '' AS sr FROM new_rows x WHERE true) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'doc' AS ot, x."child"::text AS oid, 'parent' AS rel, 'doc' AS st, x."parent"::text AS sid, '' AS sr FROM new_rows x WHERE true) c GROUP BY c.ot;
  RETURN NULL;
END $f$;
-- @object trigger "authz_rel_audit_1_ins" ON "alt"."doc_links"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"alt"."doc_links"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_rel_audit_1_ins" AFTER INSERT ON "alt"."doc_links" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."rel_audit_1_ins"()';
  ELSE
    RAISE NOTICE '% is not a table: changes to it are not audited or fed (audit)', '"alt"."doc_links"';
  END IF;
END $tr$;
