LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.changed('user', ARRAY(SELECT o."id"::text FROM old_rows o), 'delete');
  RETURN NULL;
END $f$;
