CREATE FUNCTION authz_int."doc__view__base__start"() RETURNS SETOF bigint
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT ROWS 100 AS $f$
BEGIN
  RETURN QUERY
