  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update up after : parent.edit or {up is null}  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule alt.docs update up after'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on alt.docs'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'parent.edit';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("docs"."up")::text AS id FROM (SELECT (p_row).*) AS "docs") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('doc', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT (s."parent")::text AS id FROM (SELECT (p_row).*) AS "docs" JOIN "alt"."doc_links" s ON s."child" = "docs"."doc_no") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('doc', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || '{up is null}';
END $f$;

-- alt.docs update up after (line 47): parent.edit or {up is null}
-- Whether the rule holds for a row: called by the trigger's WHEN, which is kept parsed, as a policy is, so the app
-- role uses it without naming it (authz_int)
CREATE FUNCTION authz_int."alt.docs:column up after:holds"(p_row "alt"."docs") RETURNS boolean
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT coalesce((coalesce((up is null), false)
    OR (authz_int."doc__edit__has"("docs"."up")
    OR authz_int."doc__parent__edit__links"("docs"."doc_no"))), false) FROM pg_catalog.unnest(ARRAY[p_row]) AS "docs";
END;
-- refused: says why. The rule is checked in the trigger's WHEN below
CREATE FUNCTION authz_int."alt.docs:column up after"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "alt"."docs";
BEGIN
  -- the row as the table's own: a partition's columns may be in another order, a table that inherits may have more
  IF TG_RELID = '"alt"."docs"'::pg_catalog.regclass THEN v_row := NEW;
  ELSE v_row := pg_catalog.jsonb_populate_record(NULL::"alt"."docs", pg_catalog.to_jsonb(NEW)); END IF;
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."alt.docs:column up after:why"(v_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION 'changing up of alt.docs % needs: parent.edit or {up is null}', OLD."doc_no" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
    SCHEMA = 'alt', TABLE = 'docs', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
END $f$;
-- checked on the row after the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update_after up" BEFORE UPDATE ON "alt"."docs" FOR EACH ROW
  WHEN ((OLD."up" IS DISTINCT FROM NEW."up")
    AND pg_catalog.row_security_active('"alt"."docs"'::pg_catalog.regclass)
    AND NOT authz_int."alt.docs:column up after:holds"(pg_catalog.jsonb_populate_record(NULL::"alt"."docs", pg_catalog.to_jsonb(NEW))))
  EXECUTE FUNCTION authz_int."alt.docs:column up after"();

-- Foreign keys that delete or change governed rows skip row-level security, unless a `cascade from` line
-- says they do as meant. ON UPDATE CASCADE is left out: it changes a row's reference to follow the key it names,
-- so the row still names the same row.
DO $fk$
DECLARE c record;
BEGIN
  FOR c IN SELECT con.conname, con.conrelid::regclass AS child,
                  concat_ws(' ', CASE con.confdeltype WHEN 'c' THEN 'ON DELETE CASCADE' WHEN 'n' THEN 'ON DELETE SET NULL'
                                                      WHEN 'd' THEN 'ON DELETE SET DEFAULT' END,
                                 CASE con.confupdtype WHEN 'n' THEN 'ON UPDATE SET NULL' WHEN 'd' THEN 'ON UPDATE SET DEFAULT' END) AS actions,
                  concat_ws(', and ',
                    CASE WHEN con.confdeltype IN ('c', 'n', 'd') THEN format('deleting a row of %s also %s rows of %s', con.confrelid::regclass,
                      CASE con.confdeltype WHEN 'c' THEN 'deletes' ELSE 'changes' END, con.conrelid::regclass) END,
                    CASE WHEN con.confupdtype IN ('n', 'd') THEN format('changing the key of a row of %s also changes rows of %s', con.confrelid::regclass, con.conrelid::regclass) END) AS effects,
                  CASE WHEN con.confdeltype <> 'c' THEN 'change' WHEN con.confupdtype IN ('n', 'd') THEN 'delete or change' ELSE 'delete' END AS verb,
                  -- the line that says it is meant, with the tables as a policy writes them (and the key's columns
                  -- where another key of the table to the same one acts too)
                  (SELECT n.nspname || '.' || r.relname FROM pg_class r JOIN pg_namespace n ON n.oid = r.relnamespace WHERE r.oid = con.conrelid) AS rules,
                  'cascade from ' || (SELECT n.nspname || '.' || r.relname FROM pg_class r JOIN pg_namespace n ON n.oid = r.relnamespace WHERE r.oid = con.confrelid)
                    || CASE WHEN EXISTS (SELECT 1 FROM pg_constraint o WHERE o.contype = 'f' AND o.conrelid = con.conrelid AND o.confrelid = con.confrelid
                                           AND o.oid <> con.oid AND (o.confdeltype IN ('c', 'n', 'd') OR o.confupdtype IN ('n', 'd')))
                       THEN ' (' || (SELECT string_agg(a.attname, ', ' ORDER BY k.n) FROM unnest(con.conkey) WITH ORDINALITY k(attnum, n)
                                     JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = k.attnum) || ')' ELSE '' END AS line
           FROM pg_constraint con
           WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd'))
             AND con.conrelid IN ('"alt"."docs"'::regclass) LOOP
    RAISE WARNING 'foreign key % on % is %: %. Foreign key actions skip row-level security, so a user could % rows the policy doesn''t let them %. Use RESTRICT, or if that is meant, say so under rules %: %',
      c.conname, c.child, c.actions, c.effects, c.verb, c.verb, c.rules, c.line;
  END LOOP;
END $fk$;

-- Column privileges: masked columns are read through the masked view only
DO $mc$
DECLARE r record; cols text;
BEGIN
  -- tables that are no longer masked get back the table-wide SELECT they had
  FOR r IN SELECT * FROM authz.masked_tables WHERE (tbl || '|' || role) <> ALL (ARRAY[]::text[]) LOOP
    IF to_regclass(r.tbl) IS NOT NULL AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN
      EXECUTE format('GRANT SELECT ON %s TO %I', r.tbl, r.role);
    END IF;
    DELETE FROM authz.masked_tables WHERE tbl = r.tbl AND role = r.role;
  END LOOP;

END $mc$;

CREATE TABLE authz_int.masked_columns (tbl text, col text, view text, PRIMARY KEY (tbl, col));

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage_roles' THEN RETURN EXISTS (SELECT 1 FROM "alt"."users" o WHERE o."id" = v_bigint AND (coalesce(o."id" = (SELECT authz.uid()), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'grp' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "alt"."groups" o WHERE o."gid" = v_bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'proj' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "alt"."projects" o WHERE o."id" = v_bigint AND ((coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."proj__team" v WHERE v.id = o."id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'doc' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "alt"."docs" o WHERE o."doc_no" = v_bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "alt"."docs" o WHERE o."doc_no" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."doc__writer" v WHERE v.id = o."doc_no")
    AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (NOT coalesce(coalesce(o."blocked_id" = (SELECT authz.uid()), false), false)
    AND EXISTS (SELECT 1 FROM authz_int."doc__reader" v WHERE v.id = o."doc_no"))
    OR (EXISTS (SELECT 1 FROM authz_int."proj__view" v WHERE v.id = o."project_id")
    OR EXISTS (SELECT 1 FROM authz_int."doc__project__view__ext" v WHERE v.id = o."doc_no"))
    OR EXISTS (SELECT 1 FROM authz_int."doc__roles:view" v WHERE v.id = o."doc_no")
    OR EXISTS (SELECT 1 FROM authz.shares g WHERE g.object_type = 'doc' AND g.object_id = o."doc_no"::text AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND authz_int."doc__view__base__has"(g.subject_id::bigint))
    OR (coalesce((not exists (select 1 from alt.holds h where h.target = o.doc_no)), false)
    AND (authz_int."doc__view__base__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__view__base__has"(s."parent")))))
    AND NOT coalesce((EXISTS (SELECT 1 FROM authz_int."doc__banned" v WHERE v.id = o."doc_no")
    OR (authz_int."doc__hidden__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__hidden__has"(s."parent")))
    OR EXISTS (SELECT 1 FROM authz.shares g WHERE g.object_type = 'doc' AND g.object_id = o."doc_no"::text AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND authz_int."doc__hidden__has"(g.subject_id::bigint))), false)))
    OR (coalesce((not locked), false)
    AND NOT coalesce((exists (select 1 from alt.holds h where h.target = o.up)), false)
    AND (authz_int."doc__edit__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__edit__has"(s."parent")))))));
        WHEN 'hidden' THEN RETURN EXISTS (SELECT 1 FROM "alt"."docs" o WHERE o."doc_no" = v_bigint AND ((EXISTS (SELECT 1 FROM authz_int."doc__banned" v WHERE v.id = o."doc_no")
    OR (authz_int."doc__hidden__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__hidden__has"(s."parent")))
    OR EXISTS (SELECT 1 FROM authz.shares g WHERE g.object_type = 'doc' AND g.object_id = o."doc_no"::text AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND authz_int."doc__hidden__has"(g.subject_id::bigint)))));
        WHEN 'publish' THEN RETURN EXISTS (SELECT 1 FROM "alt"."docs" o WHERE o."doc_no" = v_bigint AND ((NOT coalesce((locked), false)
    AND (EXISTS (SELECT 1 FROM authz_int."doc__roles:publish" v WHERE v.id = o."doc_no")
    OR (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."doc__writer" v WHERE v.id = o."doc_no")
    AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (NOT coalesce(coalesce(o."blocked_id" = (SELECT authz.uid()), false), false)
    AND EXISTS (SELECT 1 FROM authz_int."doc__reader" v WHERE v.id = o."doc_no"))
    OR (EXISTS (SELECT 1 FROM authz_int."proj__view" v WHERE v.id = o."project_id")
    OR EXISTS (SELECT 1 FROM authz_int."doc__project__view__ext" v WHERE v.id = o."doc_no"))
    OR EXISTS (SELECT 1 FROM authz_int."doc__roles:view" v WHERE v.id = o."doc_no")
    OR EXISTS (SELECT 1 FROM authz.shares g WHERE g.object_type = 'doc' AND g.object_id = o."doc_no"::text AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND authz_int."doc__view__base__has"(g.subject_id::bigint))
    OR (coalesce((not exists (select 1 from alt.holds h where h.target = o.doc_no)), false)
    AND (authz_int."doc__view__base__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__view__base__has"(s."parent")))))
    AND NOT coalesce((EXISTS (SELECT 1 FROM authz_int."doc__banned" v WHERE v.id = o."doc_no")
    OR (authz_int."doc__hidden__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__hidden__has"(s."parent")))
    OR EXISTS (SELECT 1 FROM authz.shares g WHERE g.object_type = 'doc' AND g.object_id = o."doc_no"::text AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND authz_int."doc__hidden__has"(g.subject_id::bigint))), false)))
    OR (coalesce((not locked), false)
    AND NOT coalesce((exists (select 1 from alt.holds h where h.target = o.up)), false)
    AND (authz_int."doc__edit__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__edit__has"(s."parent")))))))));
        WHEN 'mine' THEN RETURN EXISTS (SELECT 1 FROM "alt"."docs" o WHERE o."doc_no" = v_bigint AND (coalesce((owner_id = (SELECT authz.uid())), false)));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "alt"."docs" o WHERE o."doc_no" = v_bigint AND (((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (NOT coalesce(coalesce(o."blocked_id" = (SELECT authz.uid()), false), false)
    AND EXISTS (SELECT 1 FROM authz_int."doc__reader" v WHERE v.id = o."doc_no"))
    OR (EXISTS (SELECT 1 FROM authz_int."proj__view" v WHERE v.id = o."project_id")
    OR EXISTS (SELECT 1 FROM authz_int."doc__project__view__ext" v WHERE v.id = o."doc_no"))
    OR EXISTS (SELECT 1 FROM authz_int."doc__roles:view" v WHERE v.id = o."doc_no")
    OR EXISTS (SELECT 1 FROM authz.shares g WHERE g.object_type = 'doc' AND g.object_id = o."doc_no"::text AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND authz_int."doc__view__base__has"(g.subject_id::bigint))
    OR (coalesce((not exists (select 1 from alt.holds h where h.target = o.doc_no)), false)
    AND (authz_int."doc__view__base__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__view__base__has"(s."parent")))))
    AND NOT coalesce((EXISTS (SELECT 1 FROM authz_int."doc__banned" v WHERE v.id = o."doc_no")
    OR (authz_int."doc__hidden__has"(o."up")
    OR EXISTS (SELECT 1 FROM "alt"."doc_links" s WHERE s."child" = o."doc_no" AND authz_int."doc__hidden__has"(s."parent")))
    OR EXISTS (SELECT 1 FROM authz.shares g WHERE g.object_type = 'doc' AND g.object_id = o."doc_no"::text AND g.relation = 'shortcut' AND g.subject_type = 'doc' AND g.subject_relation = '' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL AND authz_int."doc__hidden__has"(g.subject_id::bigint))), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'user.manage_roles' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "alt"."users" o
        WHERE coalesce(o."id" = (SELECT authz.uid()), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "alt"."users" o
        WHERE coalesce(o."id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "alt"."users" o
        WHERE o."id" > p_after::bigint AND coalesce(o."id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'grp.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."gid"::text FROM "alt"."groups" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."gid"::text FROM "alt"."groups" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."gid" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."gid"::text FROM "alt"."groups" o
        WHERE o."gid" > p_after::bigint AND coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."gid" LIMIT p_limit;
      END IF;
    WHEN 'proj.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "alt"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."proj__team" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "alt"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."proj__team" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "alt"."projects" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."proj__team" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'doc.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."doc_no"::text FROM "alt"."docs" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."doc_no"::text FROM "alt"."docs" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."doc_no" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."doc_no"::text FROM "alt"."docs" o
        WHERE o."doc_no" > p_after::bigint AND coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."doc_no" LIMIT p_limit;
      END IF;
    WHEN 'doc.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."doc_no"::text FROM "alt"."docs" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."doc__writer" v WHERE v.id = o."doc_no")
    AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (NOT coalesce(coalesce(o."blocked_id" = (SELECT authz.uid()), false), false)
    AND EXISTS (SELECT 1 FROM authz_int."doc__reader" v WHERE v.id = o."doc_no"))
    OR (EXISTS (SELECT 1 FROM authz_int."proj__view" v WHERE v.id = o."project_id")
    OR EXISTS (SELECT 1 FROM authz_int."doc__project__view__ext" v WHERE v.id = o."doc_no"))
    OR EXISTS (SELECT 1 FROM authz_int."doc__roles:view" v WHERE v.id = o."doc_no")
    OR EXISTS (SELECT 1 FROM authz_int."doc__shortcut__view__base" v WHERE v.id = o."doc_no")
    OR (coalesce((not exists (select 1 from alt.holds h where h.target = o.doc_no)), false)
    AND ((EXISTS (SELECT 1 FROM authz_int."doc__view__base__direct" v WHERE v.id = o."up")
    OR EXISTS (SELECT 1 FROM authz_int."doc__view__base" v WHERE v.id = o."up"))
    OR EXISTS (SELECT 1 FROM authz_int."doc__parent__view__base__ext" v WHERE v.id = o."doc_no"))))
