BEGIN
  IF p_id IN (SELECT r."doc_no" AS id FROM "alt"."docs" r WHERE r."owner_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'owner: owner_id is you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold doc.owner';
